export const BODY: string = "\n<p>مقسم صور يقطع صورة إلى عدة قطع أصغر: قد تشكل القطع شبكة لملف اجتماعي أو أشرطة لدوار أو شرائح لطباعة صورة كبيرة على صفحات كثيرة.</p>\n<p>مقسم الصور يقسم صورًا إلى بلاطات شبكة N في M أو صفوف أفقية أو أشرطة عمودية، وينزّل القطع واحدة واحدة أو كلها معًا في ZIP: ويعمل تمامًا في متصفحك، فصورك لا تغادر جهازك أبدًا.</p>\n<p>يشرح هذا الدليل أوضاع التقسيم الثلاثة والإعدادات المسبقة وخيارات التصدير والمهام التي يناسبها كل وضع أفضل: سواء خططت لشبكة إنستغرام أو قطعت بانوراما أو قسمت لقطة طويلة.</p>\n<h2 id=\"what-is-an-image-splitter\">ما مقسم الصور؟</h2>\n<p>مقسم صور يقسم صورة واحدة إلى مجموعة صور أصغر على طول خطوط قطع مستقيمة: شبكة 3 في 3 تحوّل صورة مربعة إلى تسع بلاطات مربعة.</p>\n<p>وتقسيم أشرطة أفقية يحوّل صورة عالية إلى صفوف مكدسة، وتقسيم أشرطة عمودية يحوّل صورة واسعة إلى أعمدة جنبًا إلى جنب.</p>\n<p>وكل بلاطة ملف صورة حقيقي، لا معاينة قص: تستطيع تنزيل البلاطات واحدة واحدة أو كلها معًا في ZIP، ثم استخدامها حيث تلزم صور منفصلة: منشورات وطباعة وشرائح عرض.</p>\n<p>والتقسيم غير مدمر: الملف الأصلي لا يتغير أبدًا، وتستطيع تقسيم نفس الصورة مجددًا بضبط مختلف بقدر ما تريد: شبكة 3 في 3 اليوم وشبكة 2 في 2 غدًا.</p>\n<p>والتقسيم مختلف عن القص: القص يتخلص من جزء من صورة ليبقي قطعة، بينما التقسيم يحافظ على كل جزء ويسلمك كلها: البلاطات معًا تحتوي الصورة كلها.</p>\n<h2 id=\"grid-mode\">وضع الشبكة: بلاطات N في M</h2>\n<p>وضع الشبكة هو الوضع الرئيسي: تعيّن عدد صفوف وأعمدة، وتقسم الأداة الصورة إلى ذلك العدد من البلاطات المتساوية: شبكة 3 في 3 تعطي تسع بلاطات، وشبكة 2 في 2 تعطي أربعًا.</p>\n<p>الشبكة هي الوضع لشبكات ملف إنستغرام، حيث تسع بلاطات مربعة تشكل صورة كبيرة على صفحة الملف: وهي أيضًا الوضع لألغاز وفسيفساء وأي عمل حيث تُعرض القطع معًا. وتُقص كل بلاطة بأبعاد البكسلات الأصلية الكاملة، فصورة 3000 بكسل مقسمة في 3 في 3 تعطي تسع بلاطات 1000 بكسل: لا شيء يُصغّر ولا يُعاد أخذ عيناته، ما يحافظ على كل تفصيل.</p>\n<p>وتظهر خطوط قطع مرقمة في المعاينة، فتستطيع رؤية بالضبط أين تبدأ كل بلاطة وأين تنتهي قبل التنزيل: وإذا مر خط قطع بوجه أو تفصيل مهم، اضبط الشبكة.</p>\n<h2 id=\"horizontal-strips\">أشرطة أفقية</h2>\n<p>الأشرطة الأفقية تقطع الصورة إلى صفوف مكدسة: صورة عالية مقسمة إلى أربعة أشرطة أفقية تعطي أربع صور واسعة وقصيرة تُقرأ من أعلى إلى أسفل، كصفحات كتاب.</p>\n<p>هذا الوضع يناسب لقطات طويلة تحتاج الطباعة: لقطة صفحة كاملة عالية جدًا لورقة واحدة، لكن أربعة أشرطة أفقية تُطبع دون مشاكل على أربع صفحات. والأشرطة الأفقية تناسب أيضًا دوارات اجتماعية حيث كل شريحة تكمل الصورة نحو الأسفل: يمرر الشخص عبر الأشرطة وتتكشف الصورة بالترتيب، ما يخلق قصة.</p>\n<p>اختر عدد الأشرطة حسب الوجهة: أربعة أشرطة لأربع صفحات مطبوعة، وثلاثة لدوار من ثلاث شرائح، واثنان لتقسيم بسيط أعلى وأسفل: وللأشرطة نفس الارتفاع، فالمحتوى يُقسم بالتساوي.</p>\n<h2 id=\"vertical-strips\">أشرطة عمودية</h2>\n<p>الأشرطة العمودية تقطع الصورة إلى أعمدة جنبًا إلى جنب: بانوراما واسعة مقسمة إلى ثلاثة أشرطة عمودية تعطي ثلاث صور عالية تُقرأ من يسار إلى يمين، كألواح ثلاثية.</p>\n<p>هذا الوضع يناسب بانورامات واسعة ولافتات واسعة جدًا لمنشور أو صفحة: بانوراما مقسمة إلى أشرطة عمودية قد تُنشر كدوار حيث كل تمريرة تكشف المقطع التالي. والأشرطة العمودية تناسب أيضًا لافتات وترويسات مواقع يجب إعادة بنائها في أعمدة: مصمم يستطيع وضع كل شريط في عموده الخاص وإعادة تجميع البانوراما على الصفحة.</p>\n<p>وكما مع الأشرطة الأفقية، للأشرطة نفس العرض، فالمحتوى يُقسم بالتساوي: بانوراما بشخص في المركز قد تحتاج عددًا فرديًا من الأشرطة لإبقاء الشخص في شريط مركزي.</p>\n<h2 id=\"split-presets\">إعدادات تقسيم مسبقة</h2>\n<p>الإعدادات المسبقة هي ضبطات تقسيم بنقرة واحدة للمهام الشائعة: شبكة إنستغرام 3 في 3 هي الإعداد المسبق الأشهر، لكن الأداة تشمل أخرى لأحجام مختلفة.</p>\n<p>إعداد مسبق نقطة بداية لا قاعدة: انقر إعداد 3 في 3 لشبكة إنستغرام ثم اضبط الصفوف أو الأعمدة إذا احتاجت صورتك أو خطتك شكلًا آخر: والإعداد المسبق يوفر الوقت، لا يقيده. وتساعد الإعدادات المسبقة عندما تقسم صورًا كثيرًا: مدير وسائل تواصل اجتماعي يبني شبكة كل أسبوع قد ينقر نفس الإعداد المسبق في كل مرة ويحصل على نفس البلاطات.</p>\n<p>وإذا لم يطابق أي إعداد مسبق عملك، عيّن الصفوف والأعمدة يدويًا: شبكة 4 في 5 لملصق أو شريط 1 في 6 للافتة أو شبكة 5 في 5 لفسيفساء.</p>\n<h2 id=\"full-resolution-tiles\">بلاطات بدقة كاملة</h2>\n<p>تُقص البلاطات بأبعاد البكسلات الأصلية الكاملة، ما يعني أن تقسيمًا لا يقلل الجودة أبدًا: صورة 3000 في 3000 بكسل مقسمة إلى تسع بلاطات تعطي تسع بلاطات 1000 في 1000 بكسل، كل منها حادة مثل الجزء المقابل من الأصل.</p>\n<p>هذا مهم للطباعة والشاشات الكبيرة: بلاطة مصغرة ستبدو ناعمة عند طباعتها أو عرضها بالحجم الكامل، بينما بلاطة بدقة كاملة تحافظ على نفس التفصيل. والمقايضة هي حجم الملف: تسع بلاطات بدقة كاملة معًا تزن نحو نفس وزن الصورة الأصلية، وتقسيم 10 في 10 يعطي مئة ملف لإدارتها.</p>\n<p>ابدأ بأعلى صورة مصدر دقة لديك: صورة 600 بكسل مقسمة في 3 في 3 تعطي تسع بلاطات 200 بكسل، تبدو جيدة كمصغرات لكنها سيئة كمنشورات.</p>\n<h2 id=\"numbered-tiles-and-zip-download\">بلاطات مرقمة وتنزيل ZIP</h2>\n<p>كل بلاطة مرقمة لتعرف أين تذهب: الترقيم يتبع ترتيب القراءة: من يسار إلى يمين ومن أعلى إلى أسفل، بدءًا من الزاوية العلوية اليسرى: البلاطة واحد هي العلوية اليسرى، والبلاطة تسعة هي السفلية اليمنى في شبكة 3 في 3.</p>\n<p>الترقيم يهم خاصة لشبكات إنستغرام، حيث يجب نشر البلاطات بترتيب عكسي لتقع في الأماكن الصحيحة: الأرقام تخبر موضع كل بلاطة. ويحتوي تنزيل ZIP كل البلاطات في ملف واحد، مسماة بالترتيب: تنزيل ZIP أسرع من حفظ كل بلاطة منفصلة، ويبقي المجموعة معًا على جهازك.</p>\n<p>وتستطيع أيضًا تنزيل بلاطات منفصلة إذا احتجت واحدة أو اثنتين فقط منها: بلاطة واحدة لصورة شخصية أو شريط واحد للافتة لا يحتاج المجموعة كلها، والتنزيل المنفرد يوفر الوقت.</p>\n<h2 id=\"input-formats\">صيغ الإدخال</h2>\n<p>يقبل المقسم ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB: صور هواتف ولقطات شاشة ورسوم من أدوات تصميم تعمل دون تحويل: وصورة واحدة تُقبل في كل مرة.</p>\n<p>وصيغة البلاطات تتبع اختيارك لا الإدخال: صورة JPG قد تنتج بلاطات PNG، وPNG قد تنتج بلاطات JPG: اختر الصيغة حسب الوجهة: JPG للصور وPNG للشفافية. ولاحظ أن ضبط جودة البلاطة يظهر فقط لبلاطات JPG: بلاطات PNG دون فقدان، فلا ضبط جودة لتغييره: وإذا احتجت الملفات أصغر، اختر JPG بجودة 85 بالمئة.</p>\n<p>GIF متحركة لا تُقسم كتحريك: رفع GIF متحرك يعطيك بلاطات إطار واحد، لا مجموعة بلاطات متحركة: قسّم صورة ثابتة للشبكات والأشرطة، واحتفظ بالتحريك للملف الكامل.</p>\n<h2 id=\"transparency-and-sprite-sheets\">الشفافية وأوراق Sprites</h2>\n<p>تقسيم PNG شفاف يحافظ على الشفافية في كل بلاطة: ورقة sprites بخلايا شفافة تُقسم إلى بلاطات شفافة، وهو بالضبط ما يحتاجه المطورون.</p>\n<p>اختر PNG كصيغة بلاطة للمهام الشفافة: JPG ليس له شفافية، فبلاطة شفافة مصدرة كـJPG تكسب خلفية صلبة، غالبًا بيضاء أو سوداء: ولن ينفع ذلك لتراكبات أو أيقونات. وأوراق sprites تحتاج قصًا دقيقًا: ورقة أيقونات 32 في 32 بكسلًا مقسمة في شبكة تعطي بلاطات 32 بكسلًا بالضبط لكل منها، ما دامت أبعاد الورقة تقسم بالتساوي.</p>\n<p>وعندما لا تقسم الورقة بالتساوي، قد تختلف بلاطات الحافة قليلًا في الحجم: ذلك طبيعي في تقسيم شبكة، ويعني أن الورقة لها هامش أو فجوة يجب قصها أولًا.</p>\n<p>قص صورة المصدر إلى مضاعف دقيق أولًا لتحقيق بلاطات مثالية على مستوى البكسل.</p>\n<h2 id=\"splitting-for-print\">التقسيم للطباعة</h2>\n<p>صورة كبيرة مطبوعة على صفحات عدة هي الاستخدام الكلاسيكي للطباعة للمقسم: ملصق مقسم إلى شبكة بلاطات يُطبع على أوراق كثيرة، تقصها وتوصلها في ملصق واحد.</p>\n<p>الأشرطة الأفقية تناسب وثائق طويلة ولافتات يجب طباعتها على صفحات عدة: إنفوغرافيك عالٍ مقسم إلى أربعة أشرطة يُطبع على أربع صفحات، كل منها قسم. وراجع أبعاد البلاطات مقابل حجم الورق قبل الطباعة: بلاطة أعرض من منطقة الطباعة تقصها الطابعة، بينما بلاطة أصغر بكثير تهدر ورقًا.</p>\n<p>اطبع بدقة كاملة ولا تدع الطابعة تقيس البلاطات: بلاطة مقيسة تفقد الحدة التي حافظ عليها التقسيم بدقة كاملة: اضبط الطابعة على الحجم الحقيقي.</p>\n<h2 id=\"splitting-screenshots\">تقسيم لقطات الشاشة</h2>\n<p>اللقطات الطويلة هي أكثر ما يقسمه الناس: لقطة صفحة كاملة لموقع أو محادثة عالية جدًا لقراءتها بارتياح وعالية جدًا لطباعتها، لكن الأشرطة تجعلها قابلة للإدارة.</p>\n<p>الصق لقطة مباشرة من الحافظة بـCtrl+V: يقبل المقسم صورًا ملصوقة، فلا تحتاج لقطة أبدًا إلى حفظها أولًا كملف: الصق واختر عدد الأشرطة ونزّل. واختر عدد الأشرطة حسب المحتوى: لقطة بأربعة أقسام طبيعية تُقسم إلى أربعة أشرطة، بينما صفحة طويلة جدًا قد تحتاج ستة أو ثمانية: أشرطة أكثر تعني قطعًا أصغر وأسهل قراءة.</p>\n<p>واحذر خطوط قطع تمر عبر نص: حد شريط يعبر سطر نص يجعل الشريطين صعبي القراءة: اضبط عدد الأشرطة حتى تقع الحدود بين فقرات.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة</h2>\n<p>أكثر خطأ شيوعًا تقسيم صورة بدقة منخفضة إلى بلاطات كثيرة جدًا: صورة 600 بكسل مقسمة في 3 في 3 تعطي تسع بلاطات 200 بكسل، تبدو سيئة كمنشورات: ابدأ بأعلى دقة لديك.</p>\n<p>خطأ آخر خط قطع يمر بوجه أو تفصيل رئيسي: المعاينة تُظهر خطوط القطع قبل التنزيل، فراجعها واضبط الشبكة أو موضع الصورة. وخطأ ثالث اختيار صيغة بلاطة خطأ: بلاطات شفافة مصدرة كـJPG تفقد شفافيتها وتكسب خلفية صلبة: اختر PNG كلما همت الشفافية.</p>\n<p>وأخيرًا، كثير من الناس ينسى ترتيب النشر للشبكات: إنستغرام يعرض أحدث منشور أولًا، فبلاطات الشبكة يجب نشرها بترتيب عكسي لتقع في الأماكن الصحيحة.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق للتقسيم</h2>\n<p>ابدأ بصورة مصدر كبيرة، واختر وضع شبكة أو أفقي أو عمودي، وعيّن الصفوف والأعمدة أو انقر إعدادًا مسبقًا: راجع خطوط القطع المرقمة في المعاينة، خاصة حول الوجوه والنص.</p>\n<p>اختر JPG للصور وPNG للشفافية، ونزّل ZIP وانشر بلاطات الشبكة بترتيب عكسي: وإذا خرج قص سيئًا، غيّر الشبكة وقسّم مجددًا بدل قبوله.</p>\n<p>للنسخة خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-taqsim-as-sura/\">كيف تقسم صورة</a>، ولشبكة إنستغرام بالتفصيل، اقرأ <a href=\"/ar/blog/taqsim-as-suwar-li-shabakat-instagram/\">تقسيم صور لشبكات وألغاز إنستغرام</a>. وقسّم صورتك بـ<a href=\"/ar/taqsim-as-suwar/\">مقسم الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين تقسيم صورة وقصها؟","answer":"القص يحافظ على قطعة من صورة ويتخلص من البقية: والتقسيم يحافظ على كل قطعة ويسلمك كلها كملفات منفصلة. والبلاطات معًا تحتوي الصورة الأصلية كلها، فقط مقسمة على طول خطوط مستقيمة."},{"question":"هل التقسيم سيقلل جودة صورتي؟","answer":"لا، تُقص البلاطات بأبعاد البكسلات الأصلية الكاملة، فكل بلاطة حادة مثل الجزء المقابل من صورة المصدر: وتنخفض الجودة فقط إذا بدأت بصورة بدقة منخفضة."},{"question":"ما أكبر شبكة أستطيع تقسيم صورة إليها؟","answer":"أقصى شبكة هي 10 في 10، ما يعطي 100 بلاطة من صورة واحدة: ومعظم المهام تحتاج أقل بكثير: 3 في 3 لشبكة إنستغرام، أو 2 في 2 لتقسيم بسيط، أو بضعة أشرطة للطباعة."},{"question":"هل أستطيع تقسيم صورة إلى قطع غير متساوية؟","answer":"لا، يقسم المقسم الصورة إلى بلاطات أو أشرطة متساوية: وإذا لم تقسم أبعاد الصورة بالتساوي، قد تختلف بلاطات الحافة ببكسل أو بكسلين. ولقطع غير متساوية دقيقة، قص كل قطعة منفصلة."},{"question":"هل تحافظ البلاطات المقسمة على صيغة الملف الأصلية؟","answer":"أنت تختار صيغة البلاطات: صورة JPG قد تنتج بلاطات PNG وPNG قد تنتج بلاطات JPG. واختر JPG للصور والملفات الصغيرة، وPNG عندما تحتاج شفافية أو بكسلات دقيقة."},{"question":"لماذا أقسم صورة بدل نشر الصورة الكاملة؟","answer":"التقسيم ينفع لمهام لا تستطيع صورة واحدة فعلها: لغز شبكة على صفحة ملف، أو دوار يكشف بانوراما تمريرة تمريرة، أو ملصق مطبوع على صفحات كثيرة، أو لقطة طويلة مقسمة إلى أقسام قابلة للقراءة."}];
